function stageBucketFor(order) {
  if (order.transportMode) {
    if (order.currentStatus === CANCELLED_STATUS) return "cancelled";
    if (isLogisticsTerminal(order.currentStatus)) return "delivered";
    return "active";
  }
  switch (order.currentStatus) {
    case "Order received":
    case "Processing":
    case "In transit":
    case "Out for delivery":
      return "active";
    case "Delayed":
      return "delayed";
    case "Delivered":
      return "delivered";
    case "Cancelled":
    case "Failed delivery":
      return "cancelled";
    default:
      return null;
  }
}
